select sessions.id, sessions.customer_id, sessions.browser, t.purchase_duration_sec, t.latest_event_time from sessions left join (select session_id, sum(case when event_type = 'purchase' then duration_sec else 0 end) as purchase_duration_sec, max(event_time) as latest_event_time from web_events where to_date(event_time) >= '2024-03-27' group by session_id) t on sessions.id = t.session_id
